export const WAVE_11_MODE_REFERENCE_SCENES = Object.freeze(Object.fromEntries(STAGE_ANIMATION_WAVE_11.filter((_, i) => i % 2 === 0).map((p, i) => [p.universes[0], Object.freeze({ Combat: p.sourceScene, RPG: p.sourceScene, Melee: STAGE_ANIMATION_WAVE_11[i * 2 + 1].sourceScene, Tactics: STAGE_ANIMATION_WAVE_11[i * 2 + 1].sourceScene })])));

const TAU = Math.PI * 2;
const line = (c, pts) => { c.beginPath(); pts.forEach((p, i) => i ? c.lineTo(...p) : c.moveTo(...p)); c.stroke(); };
const polygon = (c, pts) => { c.beginPath(); pts.forEach((p, i) => i ? c.lineTo(...p) : c.moveTo(...p)); c.closePath(); c.stroke(); };
const oval = (c, x, y, rx, ry = rx) => { c.beginPath(); c.ellipse(x, y, Math.max(.00001, rx), Math.max(.00001, ry), 0, 0, TAU); c.stroke(); };
const polar = (x, y, r, a) => [x + r * Math.cos(a), y + r * Math.sin(a)];
const unit = (w, h) => Math.min(w, h);

/** Coordinates consumed directly by the drawing path; all units scale together. */
export function getStageAnimationWave11Geometry(animation, progress, width, height) {
  const u = unit(width, height), cx = width * .5, cy = height * .325, a = TAU * progress;
  return animation.blueprint.map(part => {
    const [kind, nx, ny, nw, nh = 0, ...options] = part, x = cx + nx * u, y = cy + ny * u, w = nw * u, h = nh * u;
    const g = { kind, x, y, w, h, options };
    if (kind === 'hinge' || kind === 'bamboo') { g.angle = options[0] + options[1] * (1 - Math.cos(a)) / 2; g.root = [x, y]; g.end = polar(x, y, w, g.angle); }
    if (kind === 'pendulum') { g.angle = Math.PI / 2 + options[0] * Math.sin(a); g.root = [x, y]; g.end = polar(x, y, w, g.angle); }
    if (kind === 'lift') g.offset = (1 - Math.cos(a)) / 2 * options[0] * u;
    if (kind === 'clock') g.ends = [polar(x, y, w * .68, a * 12 - Math.PI / 2), polar(x, y, w * .44, a - Math.PI / 2)];
    return g;
  });
}

/** Authored empty architecture / botanical landscape. No state or wall clock. */
export function drawStageAnimationWave11(ctx, animation, frame, width, height) {
  if (!animation.blueprint) return false;
  const t = frame.progress, a = TAU * t, u = unit(width, height);
  ctx.strokeStyle = animation.color; ctx.fillStyle = animation.color; ctx.lineWidth = Math.max(.7, u * .0018); ctx.globalAlpha = .16;
  for (const g of getStageAnimationWave11Geometry(animation, t, width, height)) {
    const { kind, x, y, w, h, options: o } = g;
    switch (kind) {
      case 'box': case 'beam': case 'pile': case 'mast': ctx.strokeRect(x, y, w, h); break;
      case 'circle': oval(ctx, x, y, w); break;
      case 'arch': line(ctx, [[x,y+h],[x,y+h*.28],[x+w*.17,y],[x+w*.83,y],[x+w,y+h*.28],[x+w,y+h]]); break;
      case 'roof': line(ctx, [[x,y+h],[x+w*.5,y],[x+w,y+h]]); break;
      case 'cross': ctx.strokeRect(x,y,w,h); line(ctx,[[x+w*.5,y],[x+w*.5,y+h]]);line(ctx,[[x,y+h*.5],[x+w,y+h*.5]]); break;
      case 'bars': case 'screen': case 'tiles': case 'floor': {
        ctx.strokeRect(x,y,w,h); const n=o[0];for(let i=1;i<n;i++)line(ctx,[[x+w*i/n,y],[x+w*i/n,y+h]]);
        if(kind==='screen'||kind==='tiles'||kind==='floor')for(let i=1;i<4;i++)line(ctx,[[x,y+h*i/4],[x+w,y+h*i/4]]);break;
      }
      case 'hinge': case 'bamboo': {
        const normal=[-Math.sin(g.angle)*h,Math.cos(g.angle)*h];polygon(ctx,[g.root,g.end,[g.end[0]+normal[0],g.end[1]+normal[1]],[x+normal[0],y+normal[1]]]);oval(ctx,x,y,u*.008);
        if(kind==='bamboo'){line(ctx,[[x,y+h*2],[x,y+u*.13]]);for(let i=1;i<4;i++){const p=polar(x,y,w*i/4,g.angle);line(ctx,[p,[p[0]+normal[0],p[1]+normal[1]]]);}}break;
      }
      case 'split': { const q=(1-Math.cos(a))/2*o[0]*u;ctx.strokeRect(x-q,y,w*.5,h);ctx.strokeRect(x+w*.5+q,y,w*.5,h);break; }
      case 'slider': { const q=(1-Math.cos(a))/2,xx=x+o[0]*u*q, yy=y+o[1]*u*q;ctx.strokeRect(xx,yy,w,h);for(let i=1;i<o[2];i++)line(ctx,[[xx+w*i/o[2],yy],[xx+w*i/o[2],yy+h]]);line(ctx,[[x,y+h+u*.015],[x+w+o[0]*u,y+h+u*.015]]);break; }
      case 'gate': case 'shutters': { const q=.12+o[0]*(1-Math.cos(a))/2;for(const side of [-1,1]){const root=x+(side<0?0:w),end=root-side*w*.5*Math.cos(q);polygon(ctx,[[root,y],[end,y+h*.09*Math.sin(q)],[end,y+h],[root,y+h]]);for(let i=1;i<4;i++){const xx=root+(end-root)*i/4;line(ctx,[[xx,y+h*.08],[xx,y+h*.92]]);}}break; }
      case 'sash': { const q=(1-Math.cos(a))/2*o[0]*u;ctx.strokeRect(x,y+q,w,h*.5);ctx.strokeRect(x,y+h*.5,w,h*.5);break; }
      case 'shutter': { const q=(1-Math.cos(a))/2*o[0]*u;ctx.strokeRect(x,y,w,h-q);for(let i=1;i<o[1];i++){const yy=y+i*h/o[1];if(yy<y+h-q)line(ctx,[[x,yy],[x+w,yy]]);}oval(ctx,x+w*.5,y,w*.5,u*.016);break; }
      case 'portcullis': { const q=(1-Math.cos(a))/2*o[0]*u;ctx.strokeRect(x,y-q,w,h);for(let i=1;i<o[1];i++){const xx=x+w*i/o[1];line(ctx,[[xx,y-q],[xx,y+h-q],[xx-u*.008,y+h-q-u*.018]]);}for(let i=1;i<4;i++)line(ctx,[[x,y+h*i/4-q],[x+w,y+h*i/4-q]]);break; }
      case 'steps': {const n=o[0],pts=[[x,y+h]];for(let i=0;i<n;i++){pts.push([x+w*i/n,y+h-h*(i+1)/n],[x+w*(i+1)/n,y+h-h*(i+1)/n]);}line(ctx,pts);break;}
      case 'ground': line(ctx,[[x,y],[x+w*.24,y-h],[x+w*.67,y-h*.4],[x+w,y]]);break;
      case 'sea': for(let row=0;row<o[0];row++){const yy=y+h*row/o[0];line(ctx,Array.from({length:29},(_,i)=>[x+w*i/28,yy+Math.sin(a+o[1]*TAU*i/28+row*.7)*u*.008]));}break;
      case 'flow': {ctx.strokeRect(x,y,w,h);for(let i=0;i<o[0];i++){const q=(t+i/o[0])%1;line(ctx,[[x+q*w,y+h*.25],[x+Math.min(1,q+.06)*w,y+h*.5],[x+q*w,y+h*.75]]);}break;}
      case 'pool': oval(ctx,x+w*.5,y+h*.5,w*.5,h*.5);oval(ctx,x+w*.5,y+h*.5,w*.46,h*.39);for(let i=1;i<=o[0];i++)line(ctx,[[x+w*.1,y+h*i/(o[0]+1)],[x+w*.9,y+h*i/(o[0]+1)]]);break;
      case 'well': oval(ctx,x+w*.5,y,w*.5,h*.22);for(let i=0;i<o[0];i++){const yy=y+h*i/o[0];ctx.beginPath();ctx.ellipse(x+w*.5,yy,w*.5,h*.22,0,0,Math.PI);ctx.stroke();}break;
      case 'ripples': for(let i=0;i<o[0];i++){const q=(t+i/o[0])%1;oval(ctx,x,y,w*(.1+.9*q),h*(.1+.9*q));}break;
      case 'bank': polygon(ctx,[[x,y+h],[x+w*.15,y+h*.30],[x+w*.48,y],[x+w*.75,y+h*.19],[x+w,y+h*.72],[x+w,y+h]]);break;
      case 'branch': {const sway=o[1]*Math.sin(a),root=[x,y],tip=polar(x,y,h,-Math.PI/2+sway);line(ctx,[root,tip]);for(let i=1;i<=o[0];i++){const q=i/(o[0]+1),p=[root[0]+(tip[0]-root[0])*q,root[1]+(tip[1]-root[1])*q],side=i%2?1:-1,end=polar(...p,w*(.45-.2*q),-Math.PI/2+side*.8+sway);line(ctx,[p,end]);oval(ctx,...end,w*.13,h*.065);}break;}
      case 'reeds': for(let i=0;i<o[0];i++){const xx=x+w*i/o[0];ctx.beginPath();ctx.moveTo(xx,y+h);ctx.quadraticCurveTo(xx+Math.sin(a+i)*u*.008,y+h*.4,xx+Math.sin(a+i)*u*.018,y);ctx.stroke();}break;
      case 'branchline': line(ctx,Array.from({length:13},(_,i)=>[x+w*i/12,y+Math.sin(i*.2+a)*o[0]*u+h*Math.sin(Math.PI*i/12)]));break;
      case 'tendrils': for(let i=0;i<o[0];i++){const xx=x+w*i/(o[0]-1);line(ctx,Array.from({length:11},(_,j)=>[xx+Math.sin(a+i*.45+j*.25)*o[1]*u*j/10,y+h*j/10]));}break;
      case 'cloth': {const pts=[[x,y],[x+w,y]];for(let i=0;i<=8;i++){const q=i/8;pts.push([x+w*(1-q),y+h+Math.sin(a+q*TAU)*o[0]*u]);}polygon(ctx,pts);for(let i=1;i<4;i++)line(ctx,[[x+w*i/4,y],[x+w*i/4+Math.sin(a+i)*o[0]*u*.4,y+h+Math.sin(a+i)*o[0]*u]]);break;}
      case 'curtains': {const q=o[0]*u*(1-Math.cos(a))/2;for(const side of [-1,1]){const xx=x+(side<0?0:w*.5+q);const ww=w*.5-q;polygon(ctx,[[xx,y],[xx+ww,y],[xx+ww,y+h],[xx,y+h]]);for(let i=1;i<4;i++)line(ctx,[[xx+ww*i/4,y],[xx+ww*i/4+side*u*.01*Math.sin(a),y+h]]);}break;}
      case 'polecloth': line(ctx,[[x,y],[x,y+h*2.6]]);polygon(ctx,[[x,y],[x+w,y+Math.sin(a)*o[0]*u],[x+w,y+h+Math.sin(a+.5)*o[0]*u],[x,y+h]]);break;
      case 'drip': for(let i=0;i<o[0];i++){const q=(t+i/o[0])%1;oval(ctx,x+Math.sin(i)*w*.3,y+h*q*q,u*.003,u*.006);}break;
      case 'steam': for(let i=0;i<o[0];i++){const xx=x+w*i/(o[0]-1);line(ctx,Array.from({length:15},(_,j)=>[xx+u*.012*Math.sin(a+i+j*.24)*(j/14),y-h*j/14]));}break;
      case 'air': for(let i=0;i<o[0];i++)line(ctx,Array.from({length:15},(_,j)=>[x+w*j/14,y+h*i/o[0]+u*.012*Math.sin(a+j*o[1]*.24+i)]));break;
      case 'lift': {const yy=y+g.offset;line(ctx,[[x,y],[x,y+h],[x+w,y+h],[x+w,y]]);ctx.strokeRect(x+u*.012,yy,w-u*.024,u*.035);for(const xx of [x+w*.25,x+w*.75])line(ctx,[[xx,y-u*.035],[xx,yy]]);break;}
      case 'pendulum': {line(ctx,[g.root,g.end]);oval(ctx,...g.root,u*.007);const [ex,ey]=g.end;line(ctx,[[ex-h*.5,ey],[ex+h*.5,ey]]);for(let i=0;i<o[1];i++){const xx=ex-h*.5+h*i/(o[1]-1);line(ctx,[[xx,ey],[xx,ey+u*.022]]);oval(ctx,xx,ey+u*.025,u*.007);}break;}
      case 'clock': oval(ctx,x,y,w);for(let i=0;i<o[0];i++)line(ctx,[polar(x,y,w*.83,i*TAU/o[0]),polar(x,y,w*.94,i*TAU/o[0])]);for(const end of g.ends)line(ctx,[[x,y],end]);oval(ctx,x,y,u*.006);break;
      case 'dial': {ctx.beginPath();ctx.arc(x,y,w,Math.PI,TAU);ctx.stroke();line(ctx,[[x,y],polar(x,y,w*.8,Math.PI+(1-Math.cos(a))*Math.PI*.5)]);for(let i=0;i<o[0];i++)line(ctx,[polar(x,y,w*.85,Math.PI+i*Math.PI/(o[0]-1)),polar(x,y,w,Math.PI+i*Math.PI/(o[0]-1))]);break;}
      case 'bridge': {line(ctx,[[x,y],[x+w,y]]);for(let i=0;i<o[0];i++){ctx.beginPath();ctx.arc(x+w*(i+.5)/o[0],y+h,w/(o[0]*2.2),Math.PI,TAU);ctx.stroke();}line(ctx,[[x,y+h],[x+w,y+h]]);break;}
      case 'rockhole': polygon(ctx,Array.from({length:o[0]},(_,i)=>[x+w*.5+w*.5*Math.cos(i*TAU/o[0]),y+h*.5+h*.5*Math.sin(i*TAU/o[0])]));break;
      case 'octagon': polygon(ctx,Array.from({length:8},(_,i)=>[x+w*Math.cos(i*TAU/8),y+h*Math.sin(i*TAU/8)]));break;
      case 'escalator': {line(ctx,[[x,y+h],[x+w,y],[x+w,y+u*.035],[x,y+h+u*.035],[x,y+h]]);for(let i=0;i<o[0];i++){const q=(t+i/o[0])%1,xx=x+w*q,yy=y+h*(1-q);line(ctx,[[xx,yy],[xx+w/o[0],yy],[xx+w/o[0],yy-h/o[0]]]);}break;}
      case 'gutter': line(ctx,[[x,y],[x+w,y],[x+w,y+h],[x+w-u*.022,y+h],[x+w-u*.022,y+u*.025],[x,y+u*.025]]);break;
      case 'awning': {for(let i=0;i<o[0];i++){const xx=x+w*i/o[0],yy=y+h+Math.sin(a+i*.7)*o[1]*u;polygon(ctx,[[xx,y],[xx+w/o[0],y],[xx+w/o[0],yy],[xx,yy]]);}break;}
      case 'ice': {const pts=[[x,y],[x+w,y]];for(let i=o[0];i>=0;i--)pts.push([x+w*i/o[0],y+h*(i%2?.45:1)]);polygon(ctx,pts);break;}
      case 'terraces': for(let i=0;i<o[0];i++){const xx=x+w*.07*i,yy=y+h*i/o[0];line(ctx,[[xx,yy],[x+w-w*.06*i,yy],[x+w-w*.06*i,yy+h/o[0]],[xx+w*.035,yy+h/o[0]]]);}break;
      case 'fan': oval(ctx,x,y,w);for(let i=0;i<o[0];i++){const q=a+i*TAU/o[0];polygon(ctx,[polar(x,y,w*.1,q),polar(x,y,w*.86,q+.12),polar(x,y,w*.73,q+.65),polar(x,y,w*.18,q+.4)]);}oval(ctx,x,y,w*.1);break;
      case 'gantry': line(ctx,[[x,y+h],[x,y],[x+w,y],[x+w,y+h]]);for(let i=0;i<5;i++)line(ctx,[[x+w*i/5,y],[x+w*(i+.5)/5,y+u*.035],[x+w*(i+1)/5,y]]);break;
      case 'guy': {const end=[x+w,y+h],mid=[x+w*.5+Math.sin(a)*o[0]*u,y+h*.5];ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(...mid,...end);ctx.stroke();break;}
      case 'bottles': for(let i=0;i<o[0];i++){const xx=x+w*i/(o[0]-1),r=h*(.35+.08*(i%3)),q=Math.PI/2+o[1]*Math.sin(a+i*.5),p=polar(xx,y,r,q);line(ctx,[[xx,y],p]);polygon(ctx,[[p[0]-u*.005,p[1]],[p[0]+u*.005,p[1]],[p[0]+u*.005,p[1]+u*.014],[p[0]+u*.012,p[1]+u*.02],[p[0]+u*.012,p[1]+u*.055],[p[0]-u*.012,p[1]+u*.055],[p[0]-u*.012,p[1]+u*.02],[p[0]-u*.005,p[1]+u*.014]]);}break;
      case 'tower': polygon(ctx,[[x,y+h],[x,y+h*.13],[x+w*.5,y],[x+w,y+h*.13],[x+w,y+h]]);break;
      case 'coolingtower': {
        const cubic=(p0,p1,p2,p3)=>Array.from({length:21},(_,i)=>{const q=i/20,r=1-q;return[0,1].map(k=>r**3*p0[k]+3*r*r*q*p1[k]+3*r*q*q*p2[k]+q**3*p3[k]);});
        polygon(ctx,[...cubic([x,y+h],[x+w*.28,y+h*.7],[x+w*.24,y+h*.35],[x+w*.10,y]),...cubic([x+w*.9,y],[x+w*.76,y+h*.35],[x+w*.72,y+h*.7],[x+w,y+h])]);
        oval(ctx,x+w*.5,y,w*.4,u*.014);break;
      }
      default: return false;
    }
  }
  return true;
}
